// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // Fuzz parameters: an address for the callee helper (we will deploy a recorder and pass its address),
    // a uint256 v and a uint256 len to determine array length; we let the fuzzer choose elements too.
    // We cannot accept a raw address as the callee because an EOA always succeeds on low-level call and records nothing.
    function testFuzz_property(uint256 v, uint256 len) public {
        // keep length reasonable but allow zero as well; property concerns non-empty arrays
        uint256 n = bound(len, 0, 8);

        // deploy a recording helper that exposes the exact function selector transferFrom(address,address,uint256)
        // so that c.call(abi.encodeWithSelector(...)) will dispatch to the declared function and recorder can record args
        Recorder rec = new Recorder();

        // build a dynamic array of addresses to pass as _tos; we will use the recorder for every entry
        // to ensure calls succeed we use the recorder whose function returns true; the mutant's extra access will revert
        // because it will attempt to read _tos[n] which is out of bounds when n>0.
        address[] memory tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = address(rec);
        }

        // choose a non-zero length case as the distinguishing domain; but we must assert a universal property that
        // in the correct contract holds for ALL inputs: when _tos is non-empty and the callee's function succeeds
        // for every element, transfer returns true (i.e., does not revert and reports true).
        // We will call c.transfer inside try/catch to observe whether it reverts.

        bool ok;
        try c.transfer(address(this), address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The UNIVERSAL property (the single assert) we check:
        // For ALL admissible inputs (including the fuzzed ones), if the input array is empty the contract requires non-empty and will revert —
        // so we restrict the asserted domain to the admissible case: when tos.length > 0 and the callee behaves normally (recorder returns true),
        // the correct contract must not revert (ok == true). The mutant that uses i<=_tos.length will attempt out-of-bounds and cause a revert
        // for some non-empty tos; therefore the single assertion below is satisfied by the reference for ALL inputs and violated by the mutant
        // for some inputs (any n>0).

        if (n > 0) {
            assertTrue(ok);
        } else {
            // when n==0, the function should revert due to require(_tos.length > 0); the property does not assert behaviour here
            // but to keep a single assertTrue requirement in all paths we assert that ok==false in this branch
            assertTrue(!ok);
        }
    }
}

// Recorder exposes the exact signature the contract calls via selector: transferFrom(address,address,uint256)
// It records the last-call args and returns true to simulate a successful callee. This makes c's external behavior observable.
contract Recorder {
    event Called(address from, address to, uint256 v);
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(from, to, v);
        return true;
    }
}
